usage:
To use this invention:
1.  Create a new `TextureRect` node in your Godot scene.
2.  Attach the `mnemonic_scavenger_map.gd` script to this `TextureRect` node.
3.  Create a new `Shader` resource (File -> New Resource -> Shader) and save it as `mnemonic_scavenger_map.gdshader` in your project. Copy the GLSL code provided below into this file.
4.  In the Inspector for your `TextureRect` node, under the `Script Variables` section, set the `Shader Path` property to `res://mnemonic_scavenger_map.gdshader`.
5.  The script will automatically create a `ViewportContainer` and a `Viewport` (named `MapViewport`) as children of the `TextureRect`.
6.  Place all your map rendering elements (e.g., `TileMap`, `Sprite2D`s, `Path2D` for routes, etc.) as children of the `MapViewport` node. This `Viewport` will render your map, and its output will be fed to the shader.
7.  Control the `degradation_amount` property of the `mnemonic_scavenger_map.gd` script from your game logic (e.g., based on player health, proximity to Silence, or memory loss events) to dynamically degrade the map.
8.  Adjust `degradation_origin` to specify where the 'eating' effect starts (e.g., player's current position on the map, converted to UV coordinates).

**GLSL Shader Code (`mnemonic_scavenger_map.gdshader`):**
glsl
shader_type canvas_item;

uniform sampler2D map_texture;
uniform float degradation_amount : hint_range(0.0, 1.0) = 0.0;
uniform vec2 degradation_origin = vec2(0.5, 0.5); // UV coordinates for the center of degradation
uniform float time = 0.0;
uniform float noise_scale : hint_range(1.0, 50.0) = 10.0;
uniform float displacement_strength : hint_range(0.0, 0.2) = 0.05;
uniform float edge_feather : hint_range(0.0, 0.5) = 0.1;

// Simple pseudo-random function
float rand(vec2 co) {
    return fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453);
}

// 2D Noise function (simplified Perlin-like)
float noise(vec2 p) {
    vec2 ip = floor(p);
    vec2 fp = fract(p);
    fp = fp * fp * (3.0 - 2.0 * fp); // Smoothstep

    float bl = rand(ip);
    float br = rand(ip + vec2(1.0, 0.0));
    float tl = rand(ip + vec2(0.0, 1.0));
    float tr = rand(ip + vec2(1.0, 1.0));

    float b = mix(bl, br, fp.x);
    float t = mix(tl, tr, fp.x);
    return mix(b, t, fp.y);
}

void fragment() {
    vec2 uv = UV;

    // Calculate distance from degradation origin
    float dist = distance(uv, degradation_origin);

    // Create a base degradation mask that expands from the origin
    float base_mask = smoothstep(degradation_amount - edge_feather, degradation_amount, dist);

    // Add procedural noise for organic tendril effect
    vec2 noise_uv = uv * noise_scale + time * 0.1;
    float noise_val = noise(noise_uv);
    float tendril_mask = smoothstep(0.4, 0.6, noise_val); // Sharpen noise into tendrils

    // Combine base mask with tendril mask. As degradation_amount increases, tendrils become more prominent.
    float final_mask = mix(base_mask, 1.0 - tendril_mask, degradation_amount);

    // Apply displacement based on noise, making degraded areas appear warped
    vec2 displacement = vec2(noise(uv * noise_scale + time * 0.2), noise(uv * noise_scale + time * 0.3)) * 2.0 - 1.0;
    displacement *= displacement_strength * degradation_amount;
    uv += displacement;

    // Sample the map texture with potentially displaced UVs
    vec4 color = texture(map_texture, uv);

    // Apply alpha masking for the 'eating' effect
    COLOR = color;
    COLOR.a *= final_mask; // Reduce alpha where degradation is high

    // Optional: Add a subtle color shift or distortion to degraded areas for visual feedback
    if (final_mask < 0.5) {
        COLOR.rgb *= vec3(1.0, 0.9, 0.8); // Slight desaturation/color shift
        COLOR.rgb += vec3(0.05, 0.02, 0.0); // Subtle reddish tint
    }
}
